const cases = [{"key": "readiness", "title": "Checking a refill", "headline": "Can I check whether it’s ready?", "description": "During demo pass 13, the pharmacy assistant offered to check a refill. Its speech check mistakenly treated that offer as a promise that the refill was ready.", "kind": "Demo pass 13 · Spoken offer", "voice": [{"id": "offer", "role": "Assistant", "line": "I can check whether it's ready for a refill, what it would cost on your plan, or book it for you."}], "evidence": [["Before review", "Failed", "The test blocked this exact sentence at commit aeb4522."], ["After review", "Passed", "The identical test allowed it at f9ec386. Demo pass 14 also recorded a successful offer."]], "trail": "27", "change": "25", "review": "Trail #27 · Speech review", "foot": "The reviewed change distinguishes checking a status from confirming one. The test used a synthetic refill that was still waiting for a pharmacist.", "source": "https://github.com/nishantshah0/namereserve/blob/68ef0f4/docs/DEMO.md#L43"}, {"key": "review", "title": "Reporting a side effect", "headline": "“Some headaches.”", "description": "A synthetic caller describes a symptom. The assistant asks one follow-up. A pharmacist reviewing the refill needs to see what the caller actually said.", "kind": "Synthetic test · Four spoken lines", "voice": [{"id": "symptom", "role": "Caller", "line": "Some headaches."}, {"id": "followup", "role": "Assistant", "line": "When did that start, and is it mild or severe?"}, {"id": "answer", "role": "Caller", "line": "About a week ago, pretty mild."}, {"id": "handoff", "role": "Assistant", "line": "Thanks, I've passed that to the pharmacist with your refill."}], "evidence": [["Voice handoff", "Passed", "The review queue contained “Headaches, since about a week ago, mild”."], ["Queue routing", "Passed", "The matching refill went to Review whether the note arrived before or after the refill request. A note about another prescription left this refill in Quick check."]], "trail": "52", "change": "50", "review": "Trail #52 · Voice follow-up", "foot": "Two roles shipped this workflow. Trail #52 covered the conversation and Trail #25 covered the matching refill in the pharmacist’s queue. All nine focused checks passed.", "source": "https://entire.com/gh/nishantshah0/-/trails/25/changes/namereserve/24"}, {"key": "orders", "title": "Two different refills", "headline": "Which refill was approved?", "description": "One synthetic order was approved; another remained pending. Hear two of the test prompts and inspect what the saved assertions actually established.", "kind": "Synthetic test · Two caller prompts", "voice": [{"id": "metformin", "role": "Caller", "line": "Is my Metformin refill approved?"}, {"id": "unspecified", "role": "Caller", "line": "Is my refill approved?"}], "evidence": [["Order record", "Passed", "One signed decision applied to the approved order. The second order remained open."], ["Spoken status", "Known failure", "The multi-turn spoken-status test remains marked as an expected failure. The separate scorer detects when approval text is substituted for the pending refill."]], "trail": "39", "change": "37", "review": "Trail #39 · Two-refill review", "foot": "These are prompts from the test. Its expected-failure status applies to the conversation as a whole. The clip makes no claim about which particular reply failed.", "source": "https://github.com/nishantshah0/namereserve/blob/68ef0f4/lib/arena/two-refill.test.ts#L108"}];
